files.content:
* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  display: grid;
  justify-content: center;
  align-items: center;
  min-width: 500px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #feafe8;
}

form {
  width: 400px;
  border: 2px solid #000;
  padding: 50px;
}

label {
  display: block;
}

label span {
  display: block;
  font-weight: 800;
  font-size: 12px;
  text-transform: uppercase;
}

input[type="range"] {
  width: 100%;
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  background-color: transparent;
}
